solution:
import { useCallback, useRef } from 'react';

type GestureConfig = {
  onDrag?: (delta: { x: number; y: number }) => void;
  onSwipe?: (dir: 'left' | 'right' | 'up' | 'down') => void;
  onTap?: () => void;
};

export function useGesture(config: GestureConfig) {
  const configRef = useRef(config);
  configRef.current = config;

  const state = useRef<{
    startX: number; startY: number; startTime: number;
    lastX: number; lastY: number; active: boolean;
  } | null>(null);

  const bind = useCallback(() => ({
    onPointerDown(e: React.PointerEvent) {
      state.current = {
        startX: e.clientX, startY: e.clientY, startTime: e.timeStamp,
        lastX: e.clientX, lastY: e.clientY, active: true,
      };
    },
    onPointerMove(e: React.PointerEvent) {
      if (!state.current?.active) return;
      const dx = e.clientX - state.current.lastX;
      const dy = e.clientY - state.current.lastY;
      state.current.lastX = e.clientX;
      state.current.lastY = e.clientY;
      configRef.current.onDrag?.({ x: dx, y: dy });
    },
    onPointerUp(e: React.PointerEvent) {
      if (!state.current) return;
      const { startX, startY, startTime } = state.current;
      state.current.active = false;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const dt = e.timeStamp - startTime;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const speed = dist / dt;
      if (dist < 10 && dt < 200) {
        configRef.current.onTap?.();
      } else if (speed > 0.3) {
        const dir = Math.abs(dx) > Math.abs(dy)
          ? (dx > 0 ? 'right' : 'left')
          : (dy > 0 ? 'down' : 'up');
        configRef.current.onSwipe?.(dir as any);
      }
      state.current = null;
    },
  }), []);

  return { bind };
}
